export const consultasAcademicas = [
  ['Reservas confirmadas por cliente', "SELECT c.nombre, c.apellido, COUNT(r.id_reserva) AS cantidad FROM cliente c JOIN reserva r ON r.cliente_id_cliente = c.id_cliente WHERE r.estado = 'CONFIRMADA' GROUP BY c.nombre, c.apellido ORDER BY cantidad DESC"],
  ['Mantenimientos por empleado', 'SELECT e.nombre, e.apellido, COUNT(m.id_mantenimiento) AS cantidad FROM hotel_consultas.empleado e JOIN hotel_consultas.mantenimiento m ON m.empleado_id_empleado = e.id_empleado WHERE m.fecha_inicio <= CURRENT_DATE GROUP BY e.nombre, e.apellido HAVING COUNT(m.id_mantenimiento) >= 1'],
  ['Servicios por check-in en 2026', 'SELECT s.nombre, SUM(c.cantidad) AS unidades FROM hotel_consultas.servicio s JOIN hotel_consultas.consumo_servicio c ON c.servicio_id_servicio = s.id_servicio JOIN hotel_consultas.estadia e ON e.id_estadia = c.estadia_id_estadia WHERE EXTRACT(YEAR FROM e.fecha_checkin) = 2026 GROUP BY s.nombre ORDER BY unidades DESC'],
  ['Habitaciones de reservas en un rango', "SELECT h.numero, COUNT(r.id_reserva) AS reservas FROM hotel_consultas.habitacion h JOIN hotel_consultas.reserva r ON r.habitacion_id_habitacion = h.id_habitacion WHERE r.fecha_entrada BETWEEN DATE '2026-01-01' AND DATE '2026-12-31' GROUP BY h.numero"],
  ['Adelantos por reserva', "SELECT r.id_reserva, COALESCE(SUM(p.monto), 0) AS total FROM hotel_consultas.reserva r LEFT JOIN hotel_consultas.pago p ON p.reserva_id_reserva = r.id_reserva AND p.tipo_pago = 'ADELANTO' GROUP BY r.id_reserva"],
  ['Clientes distintos por tipo de habitación', 'SELECT t.nombre, COUNT(DISTINCT r.cliente_id_cliente) AS clientes FROM hotel_consultas.tipo_habitacion t JOIN hotel_consultas.habitacion h ON h.tipo_habitacion_id_tipo = t.id_tipo JOIN hotel_consultas.reserva r ON r.habitacion_id_habitacion = h.id_habitacion GROUP BY t.nombre'],
  ['Tarifas sobre el promedio', 'SELECT t.nombre, f.precio_noche FROM hotel_consultas.tarifa_habitacion f JOIN hotel_consultas.tipo_habitacion t ON t.id_tipo = f.tipo_habitacion_id_tipo WHERE f.precio_noche > (SELECT AVG(precio_noche) FROM hotel_consultas.tarifa_habitacion)'],
  ['Anticipación de reservas', 'SELECT c.nombre, c.apellido, r.id_reserva, r.fecha_entrada - r.fecha_reserva AS dias FROM hotel_consultas.cliente c JOIN hotel_consultas.reserva r ON r.cliente_id_cliente = c.id_cliente ORDER BY dias DESC'],
  ['Consumos por servicio mediante CTE', 'WITH totales AS (SELECT servicio_id_servicio, SUM(cantidad) AS unidades FROM hotel_consultas.consumo_servicio GROUP BY servicio_id_servicio) SELECT s.nombre, t.unidades FROM hotel_consultas.servicio s JOIN totales t ON t.servicio_id_servicio = s.id_servicio WHERE t.unidades > 0'],
  ['Pagos por mes', 'SELECT EXTRACT(MONTH FROM fecha_pago) AS mes, SUM(monto) AS total FROM hotel_consultas.pago WHERE EXTRACT(YEAR FROM fecha_pago) = 2026 GROUP BY EXTRACT(MONTH FROM fecha_pago) ORDER BY mes'],
]
